WITH unpacked AS (SELECT id, coupon_codes, items, SIZE(items) AS num_items, attributes['device'] AS device FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'BUNDLE')) SELECT CASE WHEN num_items >= 3 THEN 'HIGH' ELSE 'LOW' END AS num_items_tier, APPROX_PERCENTILE(num_items, 0.9) AS num_items_p90, COUNT(*) AS row_count, MAX(num_items) AS max_num_items, APPROX_PERCENTILE(num_items, ARRAY(0.25, 0.5, 0.75)) AS num_items_quartiles, GROUPING(CASE WHEN num_items >= 3 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM unpacked GROUP BY ROLLUP (CASE WHEN num_items >= 3 THEN 'HIGH' ELSE 'LOW' END);
